import java.util.*;
Map returnMap = new HashMap();
String mail = account.getStringAttribute("mail");
for (Object o : idn.findIdentitiesBySearchableIdentityAttribute("email", "StartsWith", mail, "name")) {
  if (idn.getIdentityById(o.toString()) != null) {
    returnMap.put("name", o);
  }
}
try {
  Thread.sleep(100);
} catch (Exception e) {}
return returnMap;
